"""Handle index.

    If the index is negative, convert it. If the index is out of range, raise
    an IndexError.
    """
def handle_index(l: Any, index: Any) -> object {
    if (index < 0) {
        index = `type(index)((len(l) + index));
    }
    if not (0 <= index < len(l)) {
        raise IndexError("list index out of range");
    }
    return index;
}

"""
    Get the average score of a set of subscores for a student
    \n
    :param result: A dicitonary containing the results of a student \t
    :type result: {extensions : {http://www.boxinabox.nl/extensions/multiple-results : [{value, ...}], ...}, ...} \n
    :returns: The average score \t
    :rtype: double \n
    """
def getAverageScore(result: Any) -> object {
    extensions = result["extensions"][
        "http://www.boxinabox.nl/extensions/multiple-results"
    ];
    extensions = extensions.values();
    extensions = [
        elem
        for elem in `list(extensions)
        if isinstance(elem["value"], int)
    ];
    extensions = map(lambda (res: Any) { res["value"]; }, extensions);
    extensions = `list(extensions);
    if (len(extensions) == 0) {
        return 0;
    }
    return (sum(extensions) / len(extensions));
}

"""Parse a SAS token into its components.

    :param sas_token: The SAS token.
    :type sas_token: str
    :rtype: dict[str, str]
    """
def parse_sas_token(sas_token: Any) -> object {
    sas_data = {};
    token = sas_token.partition(' ')[2];
    fields = token.split('&');
    for field in fields {
        (key, value) = field.split('=', 1);
        sas_data[key.lower()] = value;
    }
    return sas_data;
}

"""Returns a triple of lists (definitions_removed,
    definitions_shared, definitions_added)"""
def get_definitions_diff(
    previous_definition_string: Any, new_definition_string: Any
) -> object {
    old_definitions = [
        i
        for i in previous_definition_string.split('|')
        if i
    ];
    new_definitions = [
        i
        for i in new_definition_string.split('|')
        if i
    ];
    return (
        `tuple(
            i
            for i in old_definitions
            if (i not in new_definitions)
        ),
        `tuple(
            i
            for i in old_definitions
            if (i in new_definitions)
        ),
        `tuple(
            i
            for i in new_definitions
            if (i not in old_definitions)
        )
    );
}
